    {(!data.channels.length||!data.providers.length)&&<div className="onboarding"><div className="onboard-intro"><span className="eyebrow">SẴN SÀNG CẤT CÁNH</span><h2>Thiết lập một lần.<br/> Sáng tạo mỗi ngày.</h2><p>Ba bước để video đầu tiên thành hiện thực.</p></div><div className="setup-steps">{[{done:!!data.channels.length,n:'01',title:'Tạo kênh nội dung',desc:'Chủ đề, khán giả và phong cách của bạn.',action:()=>setModal('channel')},{done:!!data.providers.length,n:'02',title:'Kết nối nhà cung cấp AI',desc:'Thêm API key cho kịch bản, ảnh và giọng đọc.',action:()=>setModal('provider')},{done:!!data.videos.length,n:'03',title:'Bắt đầu video đầu tiên',desc:'Một chủ đề. Một câu chuyện mới.',action:()=>setModal('create-video')}].map(s=><button onClick={s.action} key={s.n} className="setup-step"><span className={s.done?'step-number done':'step-number'}>{s.done?<Check size={18}/>:s.n}</span><div><b>{s.title}</b><p>{s.desc}</p></div><ArrowUpRight size={17}/></button>)}</div></div>}
    <div className="dashboard-columns"><section className="panel production-panel">{sectionHead('Nhịp sáng tạo','Sản lượng video trong 7 ngày gần nhất',<span className="subtle-pill">7 ngày qua</span>)}<ProductionChart videos={data.videos}/><div className="chart-legend"><i/> Video tạo mới <span>Giờ Việt Nam · UTC+7</span></div></section><section className="panel next-panel">{sectionHead('Sắp diễn ra','Lần nghiên cứu tiếp theo',<button className="icon-button" onClick={()=>go('calendar')} aria-label="Mở lịch"><ArrowUpRight size={18}/></button>)}{data.schedules.filter(s=>s.enabled&&s.nextRunAt).slice(0,3).map(s=><div className="upcoming" key={s.id}><div className="date-tile">{new Date(s.nextRunAt).toLocaleDateString('vi-VN',{day:'2-digit',timeZone:'Asia/Ho_Chi_Minh'})}<small>THÁNG {new Date(s.nextRunAt).toLocaleDateString('vi-VN',{month:'numeric',timeZone:'Asia/Ho_Chi_Minh'})}</small></div><div><b>{s.name}</b><p><Clock3 size={12}/>{date(s.nextRunAt)}</p></div><span className="live-dot"/></div>)}{!data.schedules.some(s=>s.enabled)&&<div className="mini-empty"><CalendarDays size={29}/><p>Dành chỗ cho ý tưởng tiếp theo.</p><button className="text-button" onClick={()=>setModal('schedule')}>Lên lịch sản xuất <ArrowRight size={14}/></button></div>}<button className="button ghost wide" onClick={()=>go('calendar')}>Xem lịch nội dung <ArrowRight size={14}/></button></section></div>
